/**
 * Layer 1 / 3c — N+1 Detection with Call-Counter Proxy
 * Auto-generated by the autonomous QE framework.
 *
 * Wraps the mocked API in a transparent Proxy that counts every method call.
 * Each test asserts an explicit call budget per resolver:
 *
 *   Budget = 1  → DataLoader / in-request cache present (good)
 *   Budget = N  → Known N+1 (documented, no DataLoader yet)
 *
 * If a "Budget = N" assertion drops to 1, a DataLoader was added —
 * update the assertion and remove the "known N+1" comment.
 */

import { ApolloServer } from '@apollo/server';
import { buildSubgraphSchema } from '@apollo/subgraph';
import { readFileSync } from 'fs';
import gql from 'graphql-tag';
import { ApolloServerPluginInlineTraceDisabled } from '@apollo/server/plugin/disabled';
import resolvers from '../../src/resolvers';
import API from '../../src/api';

jest.mock('../../src/api');

const typeDefs = gql(readFileSync('schema.graphql', { encoding: 'utf-8' }));

// ── proxy factory ─────────────────────────────────────────────────────────────

function makeCallCounterProxy(api: jest.Mocked<API>): {
  proxy: jest.Mocked<API>;
  counts: Record<string, number>;
} {
  const counts: Record<string, number> = {};
  const proxy = new Proxy(api, {
    get(target, prop: string) {
      const val = (target as any)[prop];
      if (typeof val !== 'function') return val;
      return (...args: any[]) => {
        counts[prop] = (counts[prop] ?? 0) + 1;
        return val.apply(target, args);
      };
    },
  });
  return { proxy, counts };
}

// ── suite ─────────────────────────────────────────────────────────────────────

describe('Generated N+1: Call-Counter Proxy', () => {
  let server: ApolloServer;

  beforeAll(() => {
    server = new ApolloServer({
      schema: buildSubgraphSchema({ typeDefs, resolvers }),
      plugins: [ApolloServerPluginInlineTraceDisabled()],
    });
  });

  afterAll(async () => { await server.stop(); });

  // ── rockets: IN-REQUEST CACHE (Budget = 1) ────────────────────────────────

  it('Launch.rocket — in-request Map cache deduplicates identical rocket IDs (budget=1)', async () => {
    const api = new API() as jest.Mocked<API>;
    const { proxy, counts } = makeCallCounterProxy(api);

    api.getLaunches.mockResolvedValue([
      { id: 'L1', rocket: 'falcon9' },
      { id: 'L2', rocket: 'falcon9' },
      { id: 'L3', rocket: 'falcon9' },
    ] as any);
    api.getRocket.mockResolvedValue({ id: 'falcon9', name: 'Falcon 9', type: 'rocket' } as any);

    const res = await server.executeOperation(
      { query: `{ launches(limit: 3) { id rocket { rocket { id name } } } }` },
      { contextValue: { api: proxy } },
    );

    expect((res.body as any).singleResult.errors).toBeUndefined();
    expect(counts['getRocket']).toBe(1);
  });

  it('Launch.rocket — two distinct rocket IDs trigger exactly 2 REST calls', async () => {
    const api = new API() as jest.Mocked<API>;
    const { proxy, counts } = makeCallCounterProxy(api);

    api.getLaunches.mockResolvedValue([
      { id: 'L1', rocket: 'falcon9'      },
      { id: 'L2', rocket: 'falconheavy'  },
      { id: 'L3', rocket: 'falcon9'      },
    ] as any);
    api.getRocket
      .mockResolvedValueOnce({ id: 'falcon9',     name: 'Falcon 9',     type: 'rocket' } as any)
      .mockResolvedValueOnce({ id: 'falconheavy', name: 'Falcon Heavy', type: 'rocket' } as any);

    const res = await server.executeOperation(
      { query: `{ launches(limit: 3) { id rocket { rocket_name } } }` },
      { contextValue: { api: proxy } },
    );

    expect((res.body as any).singleResult.errors).toBeUndefined();
    expect(counts['getRocket']).toBe(2);
  });

  // ── ships: KNOWN N+1 (Budget = N, no DataLoader) ──────────────────────────

  it('Launch.ships — KNOWN N+1: getShip called once per launch (no DataLoader)', async () => {
    const api = new API() as jest.Mocked<API>;
    const { proxy, counts } = makeCallCounterProxy(api);

    const sharedShipId = 'GO_Ms_Tree';
    api.getLaunches.mockResolvedValue([
      { id: 'L1', ships: [{ ship_id: sharedShipId }] },
      { id: 'L2', ships: [{ ship_id: sharedShipId }] },
      { id: 'L3', ships: [{ ship_id: sharedShipId }] },
    ] as any);
    api.getShip.mockResolvedValue({
      ship_id: sharedShipId,
      ship_name: 'GO Ms. Tree',
      ship_type: 'Cargo',
    } as any);

    const res = await server.executeOperation(
      { query: `{ launches(limit: 3) { id ships { id name } } }` },
      { contextValue: { api: proxy } },
    );

    expect((res.body as any).singleResult.errors).toBeUndefined();
    // KNOWN N+1: no DataLoader for ships → 3 launches × 1 ship = 3 REST calls.
    // If this drops to 1, DataLoader was added — update assertion and remove comment.
    expect(counts['getShip']).toBe(3);
  });

  // ── history.flight: KNOWN N+1 ─────────────────────────────────────────────

  it('History.flight — KNOWN N+1: queryNextLaunch called once per history event (no DataLoader)', async () => {
    const api = new API() as jest.Mocked<API>;
    const { proxy, counts } = makeCallCounterProxy(api);

    api.getHistoryEvents.mockResolvedValue([
      { id: 'H1', title: 'First Event',  flight_number: 1 },
      { id: 'H2', title: 'Second Event', flight_number: 2 },
    ] as any);
    api.queryNextLaunch.mockResolvedValue([{ id: 'L1', name: 'Launch 1' }] as any);

    const res = await server.executeOperation(
      { query: `{ histories(limit: 2) { id title flight { id } } }` },
      { contextValue: { api: proxy } },
    );

    expect((res.body as any).singleResult.errors).toBeUndefined();
    // KNOWN N+1: each history event fires one queryNextLaunch — no batching.
    expect(counts['queryNextLaunch']).toBe(2);
  });

  // ── LaunchRocketFirstStageCore.core: KNOWN N+1 ────────────────────────────

  it('LaunchRocketFirstStageCore.core — KNOWN N+1: getCore called once per core entry', async () => {
    const api = new API() as jest.Mocked<API>;
    const { proxy, counts } = makeCallCounterProxy(api);

    api.getLaunches.mockResolvedValue([{
      id: 'L1',
      rocket: {
        first_stage: {
          cores: [
            { core_serial: 'B1049', reused: true  },
            { core_serial: 'B1050', reused: false },
          ],
        },
      },
    }] as any);
    api.getCore.mockResolvedValue({ id: 'B1049', status: 'active', reuse_count: 5 } as any);

    const res = await server.executeOperation(
      {
        query: `{
          launches(limit: 1) {
            id
            rocket {
              first_stage {
                cores { core { id status } }
              }
            }
          }
        }`,
      },
      { contextValue: { api: proxy } },
    );

    expect((res.body as any).singleResult.errors).toBeUndefined();
    // KNOWN N+1: each core entry triggers getCore independently.
    expect(counts['getCore']).toBe(2);
  });
});
